import React,{useState} from 'react';import {createRoot} from 'react-dom/client';import Chart from '@/components/Chart';import {createDrawing,type Drawing} from '@/lib/chartDrawTools';import {defaultChartSettings} from '@/lib/chartSettings';
import {PrecisionToolsStore} from '@/chart/precision-tools/store';import {createDefaultConfigs} from '@/chart/precision-tools/defaults';import {savePrecisionDocument,precisionObjectStorageKey} from '@/chart/precision-tools/persistence';
const start=1793700000000,candles=Array.from({length:180},(_,i)=>({timestamp:start+i*60000,open:20000+Math.sin(i/10)*5,high:20008+Math.sin(i/10)*5,low:19992+Math.sin(i/10)*5,close:20001+Math.sin(i/10)*5,volume:100}));
for(const chartId of ['undo-a:NQ','undo-b:NQ']){const store=new PrecisionToolsStore('default-workspace',chartId);const config=createDefaultConfigs().find(c=>c.toolId==='precision-line')!;store.createDraft('precision-line',config,{time:start+110*60000,logicalIndex:110,price:19996});store.updateDraft(d=>({...d,anchors:[{time:start+110*60000,logicalIndex:110,price:19996},{time:start+150*60000,logicalIndex:150,price:19996}]}));store.commitDraft();savePrecisionDocument({schemaVersion:1,workspaceId:'default-workspace',chartId,objects:store.getSnapshot().objects,savedAt:Date.now()});}
(window as any).__precisionUndoKey=precisionObjectStorageKey('default-workspace','undo-a:NQ');
function Pane({id}:{id:string}){const [drawings,setDrawings]=useState<Drawing[]>(()=>[createDrawing('trendLine',[{time:(start+110*60000)/1000,price:20003},{time:(start+150*60000)/1000,price:20006}])]);return <section data-pane={id} style={{width:720,height:600,position:'relative'}}><Chart instrument="NQ" chartInstanceId={id} keyboardActive={id === "undo-b"} candles={candles} timeframe="1m" settings={defaultChartSettings} chartingDrawings={drawings} onChartingDrawingsChange={setDrawings}/><output data-drawings={id} style={{display:'none'}}>{JSON.stringify(drawings)}</output></section>}
createRoot(document.getElementById('root')!).render(<><input aria-label="Notes"/><div style={{display:'flex'}}><Pane id="undo-a"/><Pane id="undo-b"/></div></>);
